    -- /////////////////////////////////////////////////////////////////
    INSERT INTO GT_SCP0049_VER_STD
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , OPERATION_GROUP_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              )
    SELECT DISTINCT
           DIVISION_ID
         , COMPANY_ID
         , SITE_ID
         , PLANT_ID
         , OPERATION_GROUP_ID
         , FACTORY_ID
         , OPERATION_ID
         , LINE_ID
