                                            , ATTRIBUTE71, ATTRIBUTE72, ATTRIBUTE73, ATTRIBUTE74, ATTRIBUTE75
                                            , ATTRIBUTE76, ATTRIBUTE77, ATTRIBUTE78, ATTRIBUTE79, ATTRIBUTE80
                                            , ATTRIBUTE81, ATTRIBUTE82, ATTRIBUTE83, ATTRIBUTE84, ATTRIBUTE85
                                            , ATTRIBUTE86, ATTRIBUTE87, ATTRIBUTE88, ATTRIBUTE89, ATTRIBUTE90
                                            , ATTRIBUTE91, ATTRIBUTE92, ATTRIBUTE93, ATTRIBUTE94, ATTRIBUTE95
                                            , ATTRIBUTE96, ATTRIBUTE97, ATTRIBUTE98, ATTRIBUTE99, ATTRIBUTE100
                                            , ATTRIBUTE101, ATTRIBUTE102, ATTRIBUTE103, ATTRIBUTE104, ATTRIBUTE105
                                            , ATTRIBUTE106, ATTRIBUTE107, ATTRIBUTE108, ATTRIBUTE109, ATTRIBUTE110
                                            , ATTRIBUTE111, ATTRIBUTE112, ATTRIBUTE113, ATTRIBUTE114, ATTRIBUTE115
                                            , ATTRIBUTE116, ATTRIBUTE117, ATTRIBUTE118, ATTRIBUTE119, ATTRIBUTE120
                                            , ATTRIBUTE121, ATTRIBUTE122, ATTRIBUTE123, ATTRIBUTE124, ATTRIBUTE125
                                            , ATTRIBUTE126, ATTRIBUTE127, ATTRIBUTE128, ATTRIBUTE129, ATTRIBUTE130
                                            , ATTRIBUTE131, ATTRIBUTE132, ATTRIBUTE133, ATTRIBUTE134, ATTRIBUTE135
                                            , ATTRIBUTE136, ATTRIBUTE137, ATTRIBUTE138, ATTRIBUTE139, ATTRIBUTE140
                                            , ATTRIBUTE141, ATTRIBUTE142, ATTRIBUTE143, ATTRIBUTE144, ATTRIBUTE145
                                            , ATTRIBUTE146, ATTRIBUTE147, ATTRIBUTE148, ATTRIBUTE149, ATTRIBUTE150
                                            , ATTRIBUTE151, ATTRIBUTE152, ATTRIBUTE153, ATTRIBUTE154, ATTRIBUTE155
                                            , ATTRIBUTE156, ATTRIBUTE157, ATTRIBUTE158, ATTRIBUTE159, ATTRIBUTE160
                                            , ATTRIBUTE161, ATTRIBUTE162, ATTRIBUTE163, ATTRIBUTE164, ATTRIBUTE165
                                            , ATTRIBUTE166, ATTRIBUTE167, ATTRIBUTE168, ATTRIBUTE169, ATTRIBUTE170
                                            , ATTRIBUTE171, ATTRIBUTE172, ATTRIBUTE173, ATTRIBUTE174, ATTRIBUTE175
                                            , ATTRIBUTE176, ATTRIBUTE177, ATTRIBUTE178, ATTRIBUTE179, ATTRIBUTE180
                                            , ATTRIBUTE181, ATTRIBUTE182, ATTRIBUTE183, ATTRIBUTE184, ATTRIBUTE185
                                            , ATTRIBUTE186, ATTRIBUTE187, ATTRIBUTE188, ATTRIBUTE189, ATTRIBUTE190
                                            , ATTRIBUTE191, ATTRIBUTE192, ATTRIBUTE193, ATTRIBUTE194, ATTRIBUTE195
                                            , ATTRIBUTE196, ATTRIBUTE197, ATTRIBUTE198, ATTRIBUTE199, ATTRIBUTE200 ) ) ) XA
             WHERE 1 = 1
               AND IA.COLUMN_NAME = XA.COLUMN_NAME
               AND TRIM(IA.YYYYMMDD) IS NOT NULL
               AND TRIM(XA.VALUE) IS NOT NULL;

            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Priority(1~9)'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'LINE ASSIGN'
               AND EXISTS ( SELECT 1
                              FROM GT_SCP0049_UPL_VALID B
                             WHERE 1 = 1
                               AND B.DIVISION_ID    = A.ATTRIBUTE1
                               AND B.COMPANY_ID     = A.ATTRIBUTE2
                               AND B.SITE_ID        = A.ATTRIBUTE3
                               AND B.PLANT_ID       = A.ATTRIBUTE4
                               AND B.FACTORY_ID     = A.ATTRIBUTE5
                               AND B.LINE_ID        = A.ATTRIBUTE6
                               AND B.OPERATION_ID   = A.ATTRIBUTE7
                               AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                               AND B.DATA_TYPE_1    = A.ATTRIBUTE10
                               AND B.ITEM_ID        = A.ATTRIBUTE12
                               AND ( TO_NUMBER(B.QTY) < 1
                                      OR TO_NUMBER(B.QTY) > 9
                                      OR ROUND(TO_NUMBER(B.QTY), 10) - FLOOR(ROUND(TO_NUMBER(B.QTY), 10)) != 0
                                   )
                               AND TO_NUMBER(B.QTY) != 0
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Priority(1~9). ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;

            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Yield(1~100)'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'YIELD'
               AND EXISTS ( SELECT 1
                              FROM GT_SCP0049_UPL_VALID B
                             WHERE 1 = 1
                               AND B.DIVISION_ID    = A.ATTRIBUTE1
                               AND B.COMPANY_ID     = A.ATTRIBUTE2
                               AND B.SITE_ID        = A.ATTRIBUTE3
                               AND B.PLANT_ID       = A.ATTRIBUTE4
                               AND B.FACTORY_ID     = A.ATTRIBUTE5
                               AND B.LINE_ID        = A.ATTRIBUTE6
                               AND B.OPERATION_ID   = A.ATTRIBUTE7
                               AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                               AND B.DATA_TYPE_1    = A.ATTRIBUTE10
                               AND B.ITEM_ID        = A.ATTRIBUTE12
                               AND ( TO_NUMBER(B.QTY) <= 1
                                      OR TO_NUMBER(B.QTY) > 100
                                      --OR ROUND(T.QTY, 100) - FLOOR(ROUND(T.QTY, 100)) <> 0
                                   )
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Yield(0~100). ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /*------------------ Start [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 ------------------*/
            /* ############################################################ */
            /* ESS 가상 Line 여부 확인  (단방향 등록/수정)				    */
            /* JV Real Line 기준 등록/수정 -> ESS 가상 Line 복사 적용		*/
            /* ############################################################ */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Virtual Line Data.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM SCM_MST_LINE_SN B
                             WHERE 1 = 1
                               AND B.DIVISION_ID     = A.ATTRIBUTE1
                               AND B.COMPANY_ID      = A.ATTRIBUTE2
                               AND B.SITE_ID         = A.ATTRIBUTE3
                               AND B.PLANT_ID        = A.ATTRIBUTE4
                               AND B.FACTORY_ID      = A.ATTRIBUTE5
                               AND B.LINE_ID         = A.ATTRIBUTE6
                               AND B.OPERATION_ID    = A.ATTRIBUTE7
                               AND B.ELECTRODE_TYPE  = A.ATTRIBUTE8
                               AND B.VIRTUAL_LINE_YN = 'Y'  -- ESS 가상 Line
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Virtual Line Data. ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);
            /*------------------ End [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 ------------------*/

            /* 정상(SUCCESS) 처리 */
            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = 'SUCCESS'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID         = V_PROGRAM_ID
               AND SHEET_NAME         = V_SHEET_NAME
               AND CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND UPLOAD_STATUS_CODE = 'UPLOAD';

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## SUCCESS ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* AS-IS 검증 구간은 명시 트랜잭션이 없어 문장마다 확정되므로 여기서 확정 */
            COMMIT;

        END IF;

        V_LOG_TYPE    := 'INSERT';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## INSERT DATA START ##########';
        V_DESCRIPTION := TO_CHAR(P_MODE);
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        SELECT COUNT(1)
          INTO V_COUNT
          FROM SCM_ADM_EXCEL_UPLOAD
         WHERE PROGRAM_ID         = V_PROGRAM_ID
           AND SHEET_NAME         = V_SHEET_NAME
           AND CREATED_BY         = V_CREATED_BY
           AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
           AND UPLOAD_STATUS_CODE = 'ERROR';

        --IF @p_mode > 0 AND @v_count = 0
        IF P_MODE > 0 THEN

            /* TACT TIME , DAILY CAPA 정보가 변경될때 정보 수정 */
            /* AS-IS #TMP_SCP0049_EXCEL_LOSS_UTIL_TACT → GT_SCP0049_SAVE_LOSS_UTIL_TACT */
            DELETE FROM GT_SCP0049_SAVE_LOSS_UTIL_TACT;

            /* LOSS 정보가 변경될때 정보 수정 */
            /* AS-IS #TMP_SCP0049_EXCEL_LOSS_UTIL_LOSS → GT_SCP0049_SAVE_LOSS_UTIL_LOSS */
            DELETE FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS;

            V_LOG_TYPE    := 'INSERT';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## INSERT/UPDATE SCP0049 CAPA DATA START ##########';
            V_DESCRIPTION := TO_CHAR(P_MODE);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* AS-IS BEGIN TRANSACTION SCP0049_CAPA_UPLOAD */
            SAVEPOINT SP_SCP0049_CAPA_UPLOAD;

            BEGIN   /* AS-IS BEGIN TRY */

                V_LOG_TYPE    := 'INSERT';
                N_LOG_COUNT   := N_LOG_COUNT + 1;
                V_LOG_MESSAGE := '########## MERGE SCP0049 CAPA DATA START ##########';
                V_DESCRIPTION := TO_CHAR(P_MODE);
                D_EVENT_DATE  := SYSDATE;
                P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

                /* #################################################### */
                /* 저장 전 임시 테이블 생성								*/
                /* AS-IS #TMP_SCP0049_DATA_EXCEL → GT_SCP0049_UPL_DATA	*/
                /* #################################################### */
                DELETE FROM GT_SCP0049_UPL_DATA;

                INSERT INTO GT_SCP0049_UPL_DATA
                            ( DIVISION_ID
                            , COMPANY_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , LINE_ID
                            , OPERATION_ID
                            , ELECTRODE_TYPE
                            , ATTRIBUTE9
                            , DATA_TYPE_1
                            , DATA_TYPE_2
                            , ITEM_ID
                            , LANE_QTY
                            , FINISH
                            , UOM
                            , YYYYMMDD
                            , QTY
                            , CREATED_BY )
                SELECT SUBSTR(XA.ATTRIBUTE1, 1, 30)   AS DIVISION_ID     -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE2, 1, 30)   AS COMPANY_ID      -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE3, 1, 30)   AS SITE_ID         -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE4, 1, 30)   AS PLANT_ID        -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE5, 1, 30)   AS FACTORY_ID      -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE6, 1, 30)   AS LINE_ID         -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE7, 1, 30)   AS OPERATION_ID    -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , SUBSTR(XA.ATTRIBUTE8, 1, 50)   AS ELECTRODE_TYPE  -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 데이터 타입 지정
                     , XA.ATTRIBUTE9
                     , XA.ATTRIBUTE10  AS DATA_TYPE_1
                     , XA.ATTRIBUTE11  AS DATA_TYPE_2
                     , XA.ATTRIBUTE12  AS ITEM_ID
                     , XA.ATTRIBUTE13  AS LANE_QTY
                     , XA.ATTRIBUTE14  AS FINISH
                     , XA.ATTRIBUTE15  AS UOM
                     , IA.YYYYMMDD
                     , XA.VALUE        AS QTY
                     , V_CREATED_BY    AS CREATED_BY
                  FROM ( SELECT ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                              , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                              , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15
                              , COLUMN_NAME, YYYYMMDD
                           FROM ( SELECT ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                                  , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                                  , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15
                                  , ATTRIBUTE16, ATTRIBUTE17, ATTRIBUTE18, ATTRIBUTE19, ATTRIBUTE20
