                               AND B.DATA_TYPE_1    = A.ATTRIBUTE10
                               AND B.ITEM_ID        = A.ATTRIBUTE12
                               AND ( TO_NUMBER(B.QTY) <= 1
                                      OR TO_NUMBER(B.QTY) > 100
                                      --OR ROUND(T.QTY, 100) - FLOOR(ROUND(T.QTY, 100)) <> 0
