                /* AS-IS #TMP_SCP0049_DATA_EXCEL → GT_SCP0049_UPL_DATA	*/
                /* #################################################### */
                DELETE FROM GT_SCP0049_UPL_DATA;

                INSERT INTO GT_SCP0049_UPL_DATA
                            ( DIVISION_ID
                            , COMPANY_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , LINE_ID
